import can
import cantools

class CANAutomation:
    def __init__(self, db_path, channel='PCAN_USBBUS1', bitrate=500000):
        self.db = cantools.database.load_file(db_path)
        self.bus = can.interface.Bus(channel=channel, bustype='pcan', bitrate=bitrate)

    def send_signal(self, msg_name, signal_dict):
        """按信号名发送"""
        msg_def = self.db.get_message_by_name(msg_name)
        data = msg_def.encode(signal_dict)
        msg = can.Message(arbitration_id=msg_def.frame_id, data=data)
        self.bus.send(msg)
        print(f"发送 {msg_name}: {signal_dict}")

    def recv_signal(self, msg_name, timeout=1.0):
        """等待接收指定报文并解码"""
        msg_def = self.db.get_message_by_name(msg_name)
        msg = self.bus.recv(timeout=timeout)
        if msg and msg.arbitration_id == msg_def.frame_id:
            return msg_def.decode(msg.data)
        return None

    def listen_forever(self):
        """持续打印所有报文的解析结果"""
        for msg in self.bus:
            try:
                decoded = self.db.decode_message(msg.arbitration_id, msg.data)
                print(f"ID=0x{msg.arbitration_id:X} {decoded}")
            except:
                print(f"ID=0x{msg.arbitration_id:X} 未知报文: {msg.data.hex()}")

# 使用
ca = CANAutomation('Demo.dbc')
ca.send_signal('EngineData', {'EngineSpeed': 3000, 'EngineTemp': 90})

# pytest 用例示例
import pytest
from can_automation import CANAutomation

@pytest.fixture
def ca():
    return CANAutomation('Demo.dbc', channel='PCAN_USBBUS1')

def test_engine_speed_valid_range(ca):
    ca.send_signal('EngineData', {'EngineSpeed': 3000})
    decoded = ca.recv_signal('EngineData', timeout=1.0)
    assert decoded is not None, "未收到 EngineData 报文"
    assert 0 <= decoded['EngineSpeed'] <= 8000, f"转速越界: {decoded['EngineSpeed']}"

def test_gear_position(ca):
    for gear, expected in [('P', 0), ('R', 1), ('N', 2), ('D', 3)]:
        ca.send_signal('GearStatus', {'GearPosition': expected})
        decoded = ca.recv_signal('GearStatus', timeout=0.5)
        assert decoded['GearPosition'] == expected

